-- =====================================================================
-- PMB Online UNH · 02_seed.sql (DATA DUMMY)
-- DATA DUMMY / SIMULASI, BUKAN DATA ASLI PENDAFTAR UNH.
-- Nama, NIK, NISN, email, dan nomor HP dibuat acak. Email memakai domain
-- example.com / .test yang memang dicadangkan untuk contoh.
--
-- DBMS        : PostgreSQL 14+ · jalankan SETELAH 01_schema.sql
-- WBS         : 1.1.2.4 · Fitur F-01 s.d. F-05 · UC-01 s.d. UC-07
-- Disusun oleh: Bunga Olivia (Database Officer)
-- Direview oleh: Maulana Umar Al-Faroq (CEO/PO)
-- Versi 1.0 · 24 Nov 2026 · draf dibantu AI generatif (wajib diungkapkan di refleksi)
--
-- Akun demo (password semua akun: Demo123!)
--   admin@pmb.unh.test            admin
--   ketua.panitia@pmb.unh.test    panitia (menetapkan hasil)
--   verifikator1@pmb.unh.test     panitia (verifikasi berkas)
--   verifikator2@pmb.unh.test     panitia (verifikasi berkas)
--   keuangan@pmb.unh.test         keuangan
--   baak@pmb.unh.test             baak (validasi daftar ulang & ekspor)
--   pimpinan@pmb.unh.test         pimpinan
--   pendaftar: lihat kolom email tabel pengguna (mis. pengguna_id 12 = Dimas Saputra)
--
-- Jumlah baris per tabel:
--   kampus                   1
--   peran                    6
--   kelas                    2
--   sumber_informasi         8
--   gelombang                3
--   jalur_pendaftaran        5
--   program_studi            5
--   jenis_berkas             4
--   pengguna                69
--   otp_verifikasi          66
--   calon_mahasiswa         60
--   pendaftaran             60
--   pilihan_prodi           97
--   tagihan                 75
--   pembayaran              72
--   berkas_pendaftaran     182
--   hasil_seleksi           40
--   ekspor_siakad            1
--   pendaftaran_ulang       18
--   notifikasi             332
-- =====================================================================

BEGIN;
SET TIME ZONE 'Asia/Jakarta';

-- ---------------------------------------------------------------------
-- A. MASTER · kampus, peran, kelas, sumber informasi
-- ---------------------------------------------------------------------
-- Daftar sumber informasi = asumsi tim ([daftar sumber dari panitia]).

-- ---------------------------------------------------------------------
-- B. MASTER · gelombang, jalur, program studi, jenis berkas (per kampus)
-- ---------------------------------------------------------------------
-- Gelombang 1 mengikuti wireframe (pmb.unh.ac.id). Tanggal Gelombang 2 & 3 = ASUMSI, sesuaikan jadwal resmi.

-- ---------------------------------------------------------------------
-- C. PENGGUNA · 7 akun staf demo + 62 akun pendaftar (password semua: Demo123!)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- D. OTP VERIFIKASI (kode_hash = hash palsu; kode OTP demo tidak disimpan polos)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- E. CALON MAHASISWA (NIK/NISN = angka acak berformat benar, BUKAN data asli)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- F. PENDAFTARAN & PILIHAN PRODI (semua di Gelombang 1; distribusi status lihat panduan)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- G. TAGIHAN & PEMBAYARAN (F-03: unggah bukti + verifikasi keuangan; nomor_va NULL di MVP)
-- ---------------------------------------------------------------------
-- Nominal = ASUMSI tim: formulir Rp250.000, daftar ulang Rp3.500.000 ([nominal dari Bagian Keuangan]).

-- ---------------------------------------------------------------------
-- H. BERKAS PENDAFTARAN (F-01 unggah + F-02 verifikasi; unggah ulang = baris baru)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- I. HASIL SELEKSI (F-04; ditetapkan ketua panitia, diumumkan 20 Nov 2026)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- J. EKSPOR SIAKAD & DAFTAR ULANG (F-05)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- K. NOTIFIKASI (Should S-01)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- L. SINKRONKAN SEQUENCE IDENTITY (supaya INSERT berikutnya dari aplikasi tidak bentrok ID)
-- ---------------------------------------------------------------------
DO $$
BEGIN
  PERFORM setval(pg_get_serial_sequence('kampus', 'kampus_id'), (SELECT COALESCE(MAX(kampus_id), 1) FROM kampus));
  PERFORM setval(pg_get_serial_sequence('peran', 'peran_id'), (SELECT COALESCE(MAX(peran_id), 1) FROM peran));
  PERFORM setval(pg_get_serial_sequence('kelas', 'kelas_id'), (SELECT COALESCE(MAX(kelas_id), 1) FROM kelas));
  PERFORM setval(pg_get_serial_sequence('sumber_informasi', 'sumber_informasi_id'), (SELECT COALESCE(MAX(sumber_informasi_id), 1) FROM sumber_informasi));
  PERFORM setval(pg_get_serial_sequence('gelombang', 'gelombang_id'), (SELECT COALESCE(MAX(gelombang_id), 1) FROM gelombang));
  PERFORM setval(pg_get_serial_sequence('jalur_pendaftaran', 'jalur_id'), (SELECT COALESCE(MAX(jalur_id), 1) FROM jalur_pendaftaran));
  PERFORM setval(pg_get_serial_sequence('program_studi', 'prodi_id'), (SELECT COALESCE(MAX(prodi_id), 1) FROM program_studi));
  PERFORM setval(pg_get_serial_sequence('jenis_berkas', 'jenis_berkas_id'), (SELECT COALESCE(MAX(jenis_berkas_id), 1) FROM jenis_berkas));
  PERFORM setval(pg_get_serial_sequence('pengguna', 'pengguna_id'), (SELECT COALESCE(MAX(pengguna_id), 1) FROM pengguna));
  PERFORM setval(pg_get_serial_sequence('otp_verifikasi', 'otp_id'), (SELECT COALESCE(MAX(otp_id), 1) FROM otp_verifikasi));
  PERFORM setval(pg_get_serial_sequence('calon_mahasiswa', 'calon_id'), (SELECT COALESCE(MAX(calon_id), 1) FROM calon_mahasiswa));
  PERFORM setval(pg_get_serial_sequence('pendaftaran', 'pendaftaran_id'), (SELECT COALESCE(MAX(pendaftaran_id), 1) FROM pendaftaran));
  PERFORM setval(pg_get_serial_sequence('pilihan_prodi', 'pilihan_id'), (SELECT COALESCE(MAX(pilihan_id), 1) FROM pilihan_prodi));
  PERFORM setval(pg_get_serial_sequence('berkas_pendaftaran', 'berkas_id'), (SELECT COALESCE(MAX(berkas_id), 1) FROM berkas_pendaftaran));
  PERFORM setval(pg_get_serial_sequence('tagihan', 'tagihan_id'), (SELECT COALESCE(MAX(tagihan_id), 1) FROM tagihan));
  PERFORM setval(pg_get_serial_sequence('pembayaran', 'pembayaran_id'), (SELECT COALESCE(MAX(pembayaran_id), 1) FROM pembayaran));
  PERFORM setval(pg_get_serial_sequence('hasil_seleksi', 'hasil_id'), (SELECT COALESCE(MAX(hasil_id), 1) FROM hasil_seleksi));
  PERFORM setval(pg_get_serial_sequence('ekspor_siakad', 'ekspor_id'), (SELECT COALESCE(MAX(ekspor_id), 1) FROM ekspor_siakad));
  PERFORM setval(pg_get_serial_sequence('pendaftaran_ulang', 'daftar_ulang_id'), (SELECT COALESCE(MAX(daftar_ulang_id), 1) FROM pendaftaran_ulang));
  PERFORM setval(pg_get_serial_sequence('notifikasi', 'notifikasi_id'), (SELECT COALESCE(MAX(notifikasi_id), 1) FROM notifikasi));
END $$;

COMMIT;
